import { Pool } from "pg";

export interface ShipmentRow {
  id: string;
  trackingNumber: string;
  carrierCode: string;
  weightGrams: number;
  status: string;
}

export interface StopRow {
  shipmentId: string;
  sequence: number;
  facilityCode: string;
  scheduledAt: Date;
}

export interface CarrierRow {
  code: string;
  displayName: string;
  cutoffHourUtc: number;
}

export class ManifestRepository {
  constructor(private readonly pool: Pool) {}

  async shipmentsForDepot(depotId: string, shipDate: string): Promise<ShipmentRow[]> {
    const { rows } = await this.pool.query(
      `SELECT id, tracking_number AS "trackingNumber", carrier_code AS "carrierCode",
              weight_grams AS "weightGrams", status
         FROM shipments
        WHERE depot_id = $1 AND ship_date = $2 AND status <> 'cancelled'
        ORDER BY carrier_code, id`,
      [depotId, shipDate],
    );
    return rows;
  }

  async carriersByCode(codes: string[]): Promise<Map<string, CarrierRow>> {
    if (codes.length === 0) return new Map();
    const { rows } = await this.pool.query(
      `SELECT code, display_name AS "displayName", cutoff_hour_utc AS "cutoffHourUtc"
         FROM carriers WHERE code = ANY($1)`,
      [codes],
    );
    return new Map(rows.map((r: CarrierRow) => [r.code, r]));
  }

  async stopsForShipment(shipmentId: string): Promise<StopRow[]> {
    const { rows } = await this.pool.query(
      `SELECT shipment_id AS "shipmentId", sequence, facility_code AS "facilityCode",
              scheduled_at AS "scheduledAt"
         FROM shipment_stops WHERE shipment_id = $1 ORDER BY sequence`,
      [shipmentId],
    );
    return rows;
  }

  async stopsForShipments(shipmentIds: string[]): Promise<Map<string, StopRow[]>> {
    const out = new Map<string, StopRow[]>();
    if (shipmentIds.length === 0) return out;
    const { rows } = await this.pool.query(
      `SELECT shipment_id AS "shipmentId", sequence, facility_code AS "facilityCode",
              scheduled_at AS "scheduledAt"
         FROM shipment_stops WHERE shipment_id = ANY($1) ORDER BY shipment_id, sequence`,
      [shipmentIds],
    );
    for (const r of rows as StopRow[]) {
      const list = out.get(r.shipmentId) ?? [];
      list.push(r);
      out.set(r.shipmentId, list);
    }
    return out;
  }
}

import { ManifestRepository, StopRow } from "./manifestRepository";

export interface ManifestLine {
  trackingNumber: string;
  carrier: string;
  weightKg: number;
  route: string[];
  firstStopAt: Date | null;
}

export interface CarrierManifest {
  carrier: string;
  cutoffHourUtc: number;
  lines: ManifestLine[];
  totalWeightKg: number;
}

export class ManifestService {
  constructor(private readonly repo: ManifestRepository) {}

  async buildDailyManifest(depotId: string, shipDate: string): Promise<CarrierManifest[]> {
    const shipments = await this.repo.shipmentsForDepot(depotId, shipDate);
    const carrierCodes = [...new Set(shipments.map((s) => s.carrierCode))];
    const carriers = await this.repo.carriersByCode(carrierCodes);

    const grouped = new Map<string, CarrierManifest>();
    for (const shipment of shipments) {
      const carrier = carriers.get(shipment.carrierCode);
      if (!carrier) {
        throw new Error(`unknown carrier ${shipment.carrierCode} on shipment ${shipment.id}`);
      }
      const stops: StopRow[] = await this.repo.stopsForShipment(shipment.id);
      const line: ManifestLine = {
        trackingNumber: shipment.trackingNumber,
        carrier: carrier.displayName,
        weightKg: shipment.weightGrams / 1000,
        route: stops.map((s) => s.facilityCode),
        firstStopAt: stops.length > 0 ? stops[0].scheduledAt : null,
      };
      const manifest = grouped.get(carrier.code) ?? {
        carrier: carrier.displayName,
        cutoffHourUtc: carrier.cutoffHourUtc,
        lines: [],
        totalWeightKg: 0,
      };
      manifest.lines.push(line);
      manifest.totalWeightKg += line.weightKg;
      grouped.set(carrier.code, manifest);
    }
    return [...grouped.values()];
  }
}
